def pack_customers(instance, seed: int, time_limit_s: float):
    depot = instance.depot_id
    routes = []
    unassigned_customers = list(instance.customer_ids)

    while unassigned_customers:
        route = [depot]
        current_battery = instance.vehicle.initial_soc

        for cid in unassigned_customers:
            next_node = instance.node_map[cid]
            energy_needed = energy_required(instance.node_map[route[-1]], next_node, instance.vehicle)

            if current_battery - energy_needed >= 0:
                route.append(cid)
                current_battery -= energy_needed
            else:
                break

        route.append(depot)
        states = propagate_route(instance, route)

        if all(state.battery_arrival >= 0 for state in states):
            routes.append(route)
            unassigned_customers = [cid for cid in unassigned_customers if cid not in route[1:-1]]
        else:
            # Insert charging station if route is not feasible
            for station_id in instance.station_ids:
                for i in range(1, len(route)):
                    new_route = route[:i] + [station_id] + route[i:]
                    new_states = propagate_route(instance, new_route)

                    if all(state.battery_arrival >= 0 for state in new_states):
                        routes.append(new_route)
                        unassigned_customers = [cid for cid in unassigned_customers if cid not in route[1:-1]]
                        break
                else:
                    continue
                break

    return routes

